USE salesmesh;
SET SQL_SAFE_UPDATES = 0;
DELETE cp FROM conversion_predictions cp JOIN leads l ON cp.lead_id = l.lead_id WHERE l.prospect_id IN ('NEW-0001', 'NEW-0002', 'NEW-0003', 'NEW-0004', 'NEW-0005', 'NEW-0006');
DELETE FROM leads WHERE prospect_id IN ('NEW-0001', 'NEW-0002', 'NEW-0003', 'NEW-0004', 'NEW-0005', 'NEW-0006');
SET SQL_SAFE_UPDATES = 1;
SELECT l.lead_id, l.prospect_id, cp.conversion_probability, cp.priority_tier, cp.predicted_at FROM leads l JOIN conversion_predictions cp ON cp.lead_id = l.lead_id WHERE l.prospect_id IN ('NEW-0001', 'NEW-0002', 'NEW-0003', 'NEW-0004', 'NEW-0005', 'NEW-0006');
SELECT COUNT(*) AS total_leads FROM leads;